mapper.select:

WHERE 1 = 1
--           카드 이름으로 검색 - 포함 여부

    AND c.card_name LIKE CONCAT('%', #{name}, '%')


--           카드 종류로 검색(신용 또는 체크)

    AND c.card_type = #{type}


--           카테고리로 검색 - 다중 값 가능

    AND cat.category_name IN

        #{categoryItem}



--           카드사 이름으로 검색 - 다중 값 가능

    AND cc.company_name IN

        #{cardCompanyItem}


ORDER BY c.card_id, b.benefit_id;

select EXISTS(
    select 1 from card_company where company_name=#{cardCompanyName}
)

SELECT card_id
FROM card
WHERE codef_card_name LIKE CONCAT('%', #{codefCardName}, '%');

SELECT EXISTS (
    SELECT 1
    FROM card
    WHERE card_id = #{cardId}
)

SELECT EXISTS (
    SELECT 1
    FROM user_card
    WHERE user_id = #{userId} AND card_id = #{cardId}
      AND is_deactivate = false
)

mapper.update:
UPDATE card
SET codef_card_name = #{apiCardName}
WHERE card_id = #{cardId}

mapper.select:

INNER JOIN user_card uc ON c.card_id = uc.card_id
INNER JOIN benefit_partner bp ON b.benefit_id = bp.benefit_id
WHERE uc.user_id = #{userId}
AND uc.is_deactivate = false
AND bp.partner_id = #{partnerId}
ORDER BY c.card_id, b.benefit_id;


INNER JOIN user_card uc ON c.card_id = uc.card_id
INNER JOIN benefit_partner bp ON b.benefit_id = bp.benefit_id
WHERE uc.user_id = #{userId}
AND uc.is_deleted = false
AND bp.partner_id = #{partnerId}
ORDER BY RAND()
LIMIT 1;
